import{_ as a,o as t,c as s,ai as i}from"./chunks/framework.Ci0kozOl.js";const n="/assets/3.0/images/measurement-families.png",m=JSON.parse('{"title":"Measurements","description":"","frontmatter":{},"headers":[],"relativePath":"3.0/packages/measurements.md","filePath":"3.0/packages/measurements.md","lastUpdated":1785947307000}'),o={name:"3.0/packages/measurements.md"};function r(d,e,l,c,u,h){return t(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="measurements" tabindex="-1">Measurements <a class="header-anchor" href="#measurements" aria-label="Permalink to &quot;Measurements&quot;">​</a></h1><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h2><p>The <code>Webkul\\Measurement</code> package adds a first-class <strong>measurement</strong> attribute type to UnoPim. A measurement value carries an amount <em>and</em> a unit, units belong to <strong>measurement families</strong> with conversion rules, and every stored value keeps a normalized base amount so filtering and comparison work across units.</p><p>Sometimes your catalog captures the same dimension in different units — one supplier ships lengths in centimetres, another in inches. Because every value is normalized to the family&#39;s standard unit, you may filter &quot;length greater than 1 m&quot; and match both without any per-query conversion.</p><p><img src="'+n+`" alt="Measurement families in the UnoPim admin"></p><h2 id="value-shape-and-conversion" tabindex="-1">Value Shape and Conversion <a class="header-anchor" href="#value-shape-and-conversion" aria-label="Permalink to &quot;Value Shape and Conversion&quot;">​</a></h2><p>A stored measurement value looks like:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;unit&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;cm&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;amount&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;180.0000&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;family&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Length&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;base_unit&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;m&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;base_data&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;1.800000&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;symbol&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;cm&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>Webkul\\Measurement\\Helpers\\MeasurementHelper</code> is the engine behind this shape:</p><ul><li><code>calculateBaseValue()</code> applies a unit&#39;s <code>convert_from_standard</code> operations <strong>in reverse</strong> with inverted operators (<code>mul</code>↔divide, <code>add</code>↔subtract) to normalize any unit to the family&#39;s standard unit. Up to 5 chained operations per unit are supported (<code>mul</code>, <code>div</code>, <code>add</code>, <code>sub</code>).</li><li><code>applyPrecision()</code> formats amounts using the configured decimals and strategy.</li><li><code>resolveUnitCode()</code> accepts a unit code, symbol, or any localized label (case- and whitespace-normalized) — so imports stay forgiving.</li></ul><h2 id="attribute-integration" tabindex="-1">Attribute Integration <a class="header-anchor" href="#attribute-integration" aria-label="Permalink to &quot;Attribute Integration&quot;">​</a></h2><p>The type registers itself by merging the <code>attribute_types</code> config (<code>measurement</code>). The package integrates with the rest of the platform by <strong>container rebinding</strong> — a useful pattern for extension authors:</p><ul><li>A <code>MeasurementNormalizer</code> is added to <code>AttributeNormalizerFactory</code>.</li><li>The DataTransfer <code>FieldProcessor</code>, the product <code>Importer</code> / <code>Exporter</code>, and <code>ProductAttributeValuesNormalizer</code> are swapped for measurement-aware subclasses.</li><li>Database and Elasticsearch product filters are registered through the <code>unopim.database.attribute.filters</code> / <code>unopim.elasticsearch.attribute.filters</code> container tags.</li><li>Listeners on <code>catalog.attribute.update.before</code> / <code>.after</code> validate and persist the attribute&#39;s family/unit binding, while view-render events inject the family picker into the attribute form and the unit selector into the product form.</li></ul><h2 id="configuring-precision" tabindex="-1">Configuring Precision <a class="header-anchor" href="#configuring-precision" aria-label="Permalink to &quot;Configuring Precision&quot;">​</a></h2><p>You may tune how amounts are rounded under <strong>Configuration → System Settings → Measurement</strong> (the <code>system.measurement</code> config group). The <code>strategy</code> setting defaults to <code>round</code>, which uses <code>number_format</code>; choosing <code>trim</code> instead truncates on the decimal string, avoiding binary floating-point artifacts like <code>0.29 × 100 = 28.999…</code>. The <code>amount</code> setting (default 4) controls the decimals for the entered amount, and <code>base</code> (default 6) controls the decimals for the normalized base value — both accept 0–10.</p><h2 id="recalculating-base-values" tabindex="-1">Recalculating Base Values <a class="header-anchor" href="#recalculating-base-values" aria-label="Permalink to &quot;Recalculating Base Values&quot;">​</a></h2><p>When a family&#39;s conversions or the precision settings change, stored base values go stale. You may rebuild them with a single command:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> measurement:recalculate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--family=Length] [--chunk</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">200] [--dry-run]</span></span></code></pre></div><p>The command walks every value scope (<code>common</code>, <code>locale_specific</code>, <code>channel_specific</code>, <code>channel_locale_specific</code>), rebuilds each measurement value, and writes with <code>saveQuietly()</code> — no observers fire, so it never cascades into webhooks or search indexing.</p><h2 id="validation-limits" tabindex="-1">Validation Limits <a class="header-anchor" href="#validation-limits" aria-label="Permalink to &quot;Validation Limits&quot;">​</a></h2><p><code>MeasurementFamilyValidator</code> and <code>MeasurementUnitValidator</code> enforce sensible ceilings: at most <strong>300 families</strong>, <strong>100 units per family</strong>, and <strong>5 conversions per unit</strong>. Codes must match <code>^[A-Za-z0-9_]+$</code>, and labels must contain at least one letter.</p><h2 id="data-model" tabindex="-1">Data Model <a class="header-anchor" href="#data-model" aria-label="Permalink to &quot;Data Model&quot;">​</a></h2><p>For reference, the underlying tables are:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>measurement_families              code (unique), name, standard_unit, symbol</span></span>
<span class="line"><span>measurement_family_translations   label per locale</span></span>
<span class="line"><span>measurement_units                 family FK, code, symbol, position   (unique per family)</span></span>
<span class="line"><span>measurement_unit_translations     label per locale</span></span>
<span class="line"><span>measurement_unit_conversions      unit FK, operator, value, position</span></span>
<span class="line"><span>attribute_measurement             attribute_id, family_code, unit_code</span></span></code></pre></div><p><code>MeasurementFamily</code> exposes a <strong>virtual legacy shape</strong> over the normalized tables: assigning <code>labels</code> or <code>units</code> arrays on the model upserts or replaces the translation, unit, and conversion rows on save, and the <code>units</code> accessor rebuilds the legacy array. The repositories are <code>MeasurementFamilyRepository</code> and <code>AttributeMeasurementRepository</code>.</p><h2 id="admin-routes" tabindex="-1">Admin Routes <a class="header-anchor" href="#admin-routes" aria-label="Permalink to &quot;Admin Routes&quot;">​</a></h2><p>Admin routes live under <code>admin/measurement</code> (ACL <code>catalog.measurements.*</code>): family CRUD plus mass delete (<code>admin.measurement.families.*</code>), unit CRUD per family (<code>admin.measurement.families.units.*</code>), and JSON helpers for attribute wiring (<code>measurement.attribute</code>, <code>admin.measurement.family.units</code>, <code>admin.measurement.attribute.units</code>).</p><h2 id="rest-api" tabindex="-1">REST API <a class="header-anchor" href="#rest-api" aria-label="Permalink to &quot;REST API&quot;">​</a></h2><p>The API shares the <code>v1/rest</code> prefix and middleware with the Admin API:</p><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Purpose</th></tr></thead><tbody><tr><td>GET/POST</td><td><code>/api/v1/rest/measurement</code></td><td>List / create families</td></tr><tr><td>GET/PUT/DELETE</td><td><code>/api/v1/rest/measurement/{code}</code></td><td>Read / update / delete a family</td></tr><tr><td>GET/POST</td><td><code>/api/v1/rest/units/{familyCode}</code></td><td>List / create units</td></tr><tr><td>GET/PUT/DELETE</td><td><code>/api/v1/rest/units/{familyCode}/{code}</code></td><td>Read / update / delete a unit</td></tr><tr><td>GET</td><td><code>/api/v1/rest/attribute-measurement/config/{attributeCode}</code></td><td>An attribute&#39;s family/unit binding</td></tr><tr><td>GET</td><td><code>/api/v1/rest/attribute-measurement/{familyCode}</code></td><td>Units of a family</td></tr><tr><td>POST/PUT</td><td><code>/api/v1/rest/attribute-measurement/{attributeCode}</code></td><td>Bind / update an attribute&#39;s measurement config</td></tr></tbody></table><p>API ACL keys: <code>api.catalog.measurements[.create|.edit|.delete]</code> and <code>api.catalog.measurements.units[.create|.edit|.delete]</code>.</p>`,31)])])}const g=a(o,[["render",r]]);export{m as __pageData,g as default};
